def quote(state):
    t, T, best_bid, best_ask, bid_sizes, ask_sizes, mid_history, inventory, cash, max_inventory, max_order_size, memory = state
    if not mid_history:
        mid = best_bid + (best_ask - best_bid) / 2
    else:
        mid = mid_history[-1]

    # Volume imbalance
    vol_imbalance = (bid_sizes[0] - ask_sizes[0]) / (bid_sizes[0] + ask_sizes[0]) if (bid_sizes[0] + ask_sizes[0]) else 0

    # Weighted mid (micro-price)
    if bid_sizes[0] + ask_sizes[0]:
        weighted_mid = (best_ask * bid_sizes[0] + best_bid * ask_sizes[0]) / (bid_sizes[0] + ask_sizes[0])
    else:
        weighted_mid = mid

    # Adjust bid and ask based on inventory and volume imbalance
    bid = max(best_bid - 2, int(weighted_mid - 1))
    ask = min(best_ask + 2, int(weighted_mid + 1))

    # Adjust based on inventory
    if inventory > 0:
        bid = max(bid, best_bid - 1)
    elif inventory < 0:
        ask = min(ask, best_ask + 1)

    # Ensure bid < ask
    if bid >= ask:
        bid = best_bid - 1
        ask = best_ask + 1

    # Ensure sizes are within limits and inventory constraints
    bid_size = min(max_order_size, max_inventory - inventory)
    ask_size = min(max_order_size, max_inventory + inventory)

    return {"bid": bid, "bid_size": bid_size, "ask": ask, "ask_size": ask_size}
